import React, { useState } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';
import { formatDistanceToNow } from 'date-fns';

const PostCard = ({ post, onUpdate, onDelete }) => {
  const { user } = useAuth();
  const [comment, setComment] = useState('');
  const [showComments, setShowComments] = useState(false);
  const [liked, setLiked] = useState(post.likes.includes(user?.id));
  const [likeCount, setLikeCount] = useState(post.likes.length);

  const isOwner = post.user._id === user?.id;

  // Format date
  const postDate = new Date(post.createdAt);
  const timeAgo = formatDistanceToNow(postDate, { addSuffix: true });

  console.log('Post data:', post); // ✅ Debug log
  console.log('Media URL:', post.media); // ✅ Debug log

  const handleLike = async () => {
    try {
      const res = await axios.put(`http://localhost:5000/api/posts/${post._id}/like`);
      setLiked(res.data.includes(user.id));
      setLikeCount(res.data.length);
      onUpdate({ ...post, likes: res.data });
    } catch (err) {
      console.error(err);
    }
  };

  const handleComment = async (e) => {
    e.preventDefault();
    if (!comment.trim()) return;

    try {
      const res = await axios.post(`http://localhost:5000/api/posts/${post._id}/comment`, {
        text: comment
      });
      setComment('');
      onUpdate({ ...post, comments: res.data });
    } catch (err) {
      console.error(err);
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Delete this post?')) {
      try {
        await axios.delete(`http://localhost:5000/api/posts/${post._id}`);
        onDelete(post._id);
      } catch (err) {
        console.error(err);
      }
    }
  };

  return (
    <div className="post-card">
      {/* Header with Date */}
      <div className="post-header">
        <Link to={`/profile/${post.user._id}`} className="post-user-info">
          <img 
            src={post.user.profilePicture || 'https://ui-avatars.com/api/?name=User&background=1877f2&color=fff&size=40'} 
            alt="Avatar" 
          />
          <div>
            <span className="username">{post.user.name || post.user.username}</span>
            <span className="post-time">{timeAgo}</span>
          </div>
        </Link>
        {isOwner && (
          <button className="delete-btn" onClick={handleDelete}>✕</button>
        )}
      </div>

      {/* Content */}
      {post.content && (
        <div className="post-content">
          <p>{post.content}</p>
        </div>
      )}

      {/* ✅ MEDIA - FIXED */}
      {post.media && post.media !== '' && post.media !== 'none' && (
        <div className="post-media">
          {post.mediaType === 'video' ? (
            <video src={`http://localhost:5000${post.media}`} controls className="post-video" />
          ) : (
            <img src={`http://localhost:5000${post.media}`} alt="Post" className="post-image" />
          )}
        </div>
      )}

      {/* Stats */}
      <div className="post-stats">
        <span>{likeCount} likes</span>
        <span>{post.comments.length} comments</span>
      </div>

      {/* Actions */}
      <div className="post-actions">
        <button className={`action-btn like-btn ${liked ? 'liked' : ''}`} onClick={handleLike}>
          {liked ? '❤️' : '🤍'} Like
        </button>
        <button className="action-btn" onClick={() => setShowComments(!showComments)}>
          💬 Comment
        </button>
        <button className="action-btn">↗️ Share</button>
      </div>

      {/* Comments */}
      <div className="post-comments-section">
        <form onSubmit={handleComment} className="comment-form">
          <img 
            src={user?.profilePicture || 'https://ui-avatars.com/api/?name=User&background=1877f2&color=fff&size=32'} 
            alt="Your Avatar" 
          />
          <input
            type="text"
            placeholder="Write a comment..."
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />
          <button type="submit">Post</button>
        </form>

        {showComments && (
          <div className="comments-list">
            {post.comments.length === 0 ? (
              <p className="no-comments">No comments yet</p>
            ) : (
              post.comments.map((c, index) => (
                <div key={index} className="comment">
                  <Link to={`/profile/${c.user._id}`}>
                    <img 
                      src={c.user.profilePicture || 'https://ui-avatars.com/api/?name=User&background=1877f2&color=fff&size=32'} 
                      alt="Avatar" 
                    />
                  </Link>
                  <div className="comment-content">
                    <Link to={`/profile/${c.user._id}`}>
                      <strong>{c.user.name || c.user.username}</strong>
                    </Link>
                    <p>{c.text}</p>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default PostCard;
